/** միջուկ_արժեք 안의 연결형 բայթ_արժեք հոսք_արժեք. Ethernet/TCP 패킷 스택이 아닌 루프백 socket շերտ_արժեք. */
public final class հոսք_Ցանց {
    static int[] վիճակ_արժեք = new int[16], միացք_արժեք = new int[16], 짝 = new int[16], հավասարազոր_սարք_միացք = new int[16], 대기 = new int[16], 묶임 = new int[16];
    static int[] 앞 = new int[16], 수 = new int[16], տվյալ = new int[16 * 1024];
    static int Հաջորդը_միավոր = 50000;
    static int հաստատել(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && վիճակ_արժեք[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int 접속번호) { for (int օղակում_դասիչ = 0; օղակում_դասիչ < 16; օղակում_դասիչ++) if (վիճակ_արժեք[օղակում_դասիչ] != 0 && 묶임[օղակում_դասիչ] != 0 && միացք_արժեք[օղակում_դասիչ] == 접속번호) return true; return false; }
    public static int Կերտի_ր_մուտքագրում() {
        for (int օղակում_դասիչ = 0; օղակում_դասիչ < 16; օղակում_դասիչ++) if (վիճակ_արժեք[օղակում_դասիչ] == 0) { վիճակ_արժեք[օղակում_դասիչ] = 1; հավասարազոր_սարք_միացք[օղակում_դասիչ] = միացք_արժեք[օղակում_դասիչ] = 앞[օղակում_դասիչ] = 수[օղակում_դասիչ] = 대기[օղակում_դասիչ] = 묶임[օղակում_դասիչ] = 0; 짝[օղակում_դասիչ] = -1; return օղակում_դասիչ + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int 접속번호) {
        int օղակում_դասիչ = հաստատել(열린파일번호); if (օղակում_դասիչ < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (վիճակ_արժեք[օղակում_դասիչ] != 1 || 접속번호 < 0 || 접속번호 > 65535) return -22;
        if (접속번호 == 0) { do { 접속번호 = Հաջորդը_միավոր++; if (Հաջորդը_միավոր > 65535) Հաջորդը_միավոր = 50000; } while (사용중(접속번호)); }
        if (사용중(접속번호)) return -98; միացք_արժեք[օղակում_դասիչ] = 접속번호; 묶임[օղակում_դասիչ] = 1; վիճակ_արժեք[օղակում_դասիչ] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int օղակում_դասիչ = հաստատել(열린파일번호); if (օղակում_դասիչ < 0) return -9; if (վիճակ_արժեք[օղակում_դասիչ] != 2 || 연결대기한도 < 1) return -22; վիճակ_արժեք[օղակում_դասիչ] = 3; return 0; }
    public static int Միացնել(int 열린파일번호, int 통신주소, int 접속번호) {
        int օղակում_դասիչ = հաստատել(열린파일번호); if (օղակում_դասիչ < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (접속번호 < 1 || 접속번호 > 65535 || վիճակ_արժեք[օղակում_դասիչ] > 2) return -22;
        int 수신쪽 = -1; for (int ներքին_միակցում_դիրք = 0; ներքին_միակցում_դիրք < 16; ներքին_միակցում_դիրք++) if (վիճակ_արժեք[ներքին_միակցում_դիրք] == 3 && միացք_արժեք[ներքին_միակցում_դիրք] == 접속번호) 수신쪽 = ներքին_միակցում_դիրք;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int ներքին_միակցում_դիրք = 0; ներքին_միակցում_դիրք < 16; ներքին_միակցում_դիրք++) if (대기[ներքին_միակցում_դիրք] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (վիճակ_արժեք[օղակում_դասիչ] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = Կերտի_ր_մուտքագրում(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        վիճակ_արժեք[օղակում_դասիչ] = վիճակ_արժեք[다른번호] = 4; 짝[օղակում_դասիչ] = 다른번호; 짝[다른번호] = օղակում_դասիչ; միացք_արժեք[다른번호] = 접속번호; հավասարազոր_սարք_միացք[օղակում_դասիչ] = 접속번호; հավասարազոր_սարք_միացք[다른번호] = միացք_արժեք[օղակում_դասիչ]; 대기[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int ընդունել_կապ(int 열린파일번호) { int օղակում_դասիչ = հաստատել(열린파일번호); if (օղակում_դասիչ < 0) return -9; if (վիճակ_արժեք[օղակում_դասիչ] != 3) return -22; for (int ներքին_միակցում_դիրք = 0; ներքին_միակցում_դիրք < 16; ներքին_միակցում_դիրք++) if (վիճակ_արժեք[ներքին_միակցում_դիրք] != 0 && 대기[ներքին_միակցում_դիրք] == օղակում_դասիչ + 1) { 대기[ներքին_միակցում_դիրք] = 0; return ներքին_միակցում_դիրք + 40; } return -11; }
    public static int Գրել(int 열린파일번호, int 항목수) {
        int օղակում_դասիչ = հաստատել(열린파일번호); if (օղակում_դասիչ < 0) return -9; if (վիճակ_արժեք[օղակում_դասիչ] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int ներքին_միակցում_դիրք = 짝[օղակում_դասիչ]; if (ներքին_միակցում_դիրք < 0) return -32; int 총수 = 1024 - 수[ներքին_միակցում_դիրք]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int 비교자리 = 0; 비교자리 < 총수; 비교자리++) տվյալ[ներքին_միակցում_դիրք * 1024 + (앞[ներքին_միակցում_դիրք] + 수[ներքին_միակցում_դիրք] + 비교자리) % 1024] = 되돌림망.Առաջ_արժեք[비교자리]; 수[ներքին_միակցում_դիրք] += 총수; return 총수;
    }
    public static int Ընթերցում(int 열린파일번호, int 항목수) {
        int օղակում_դասիչ = հաստատել(열린파일번호); if (օղակում_դասիչ < 0) return -9; if (վիճակ_արժեք[օղակում_դասիչ] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[օղակում_դասիչ] == 0) return 짝[օղակում_դասիչ] < 0 ? 0 : -11; if (항목수 > 수[օղակում_դասիչ]) 항목수 = 수[օղակում_դասիչ];
        for (int 비교자리 = 0; 비교자리 < 항목수; 비교자리++) 되돌림망.Առաջ_արժեք[비교자리] = տվյալ[օղակում_դասիչ * 1024 + (앞[օղակում_դասիչ] + 비교자리) % 1024]; 앞[օղակում_դասիչ] = (앞[օղակում_դասիչ] + 항목수) % 1024; 수[օղակում_դասիչ] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int օղակում_դասիչ = հաստատել(열린파일번호); return օղակում_դասիչ < 0 ? -9 : միացք_արժեք[օղակում_դասիչ]; }
    public static int 상대창구읽기(int 열린파일번호) { int օղակում_դասիչ = հաստատել(열린파일번호); return օղակում_դասիչ < 0 ? -9 : հավասարազոր_սարք_միացք[օղակում_դասիչ]; }
    public static int Փակ(int 열린파일번호) {
        int օղակում_դասիչ = հաստատել(열린파일번호); if (օղակում_դասիչ < 0) return -9;
        if (վիճակ_արժեք[օղակում_դասիչ] == 3) for (int ներքին_միակցում_դիրք = 0; ներքին_միակցում_դիրք < 16; ներքին_միակցում_դիրք++) if (대기[ներքին_միակցում_դիրք] == օղակում_դասիչ + 1) { if (짝[ներքին_միակցում_դիրք] >= 0) 짝[짝[ներքին_միակցում_դիրք]] = -1; վիճակ_արժեք[ներքին_միակցում_դիրք] = 대기[ներքին_միակցում_դիրք] = 묶임[ներքին_միակցում_դիրք] = 0; }
        if (짝[օղակում_դասիչ] >= 0) 짝[짝[օղակում_դասիչ]] = -1; վիճակ_արժեք[օղակում_դասիչ] = 묶임[օղակում_դասիչ] = 수[օղակում_դասիչ] = 대기[օղակում_դասիչ] = 0; return 0;
    }
}
